import { parse } from 'node-html-parser';

import { getAnthropicClient } from '@/lib/anthropic';

export type LegalKind = 'privacy' | 'terms';

export const LEGAL_FILES: Record<LegalKind, string> = {
  privacy: 'privacy.html',
  terms: 'terms.html',
};

export const LEGAL_NOTICE =
  'DRAFT – This text was generated by AI as a starting point. It is not legal advice and may not meet the laws that apply to you. Review and edit it, and have a qualified professional check it before you rely on it. Remove this notice only once you have done so.';

const MODEL =
  process.env.BEDROCK_MODEL_ID?.trim() ||
  'eu.anthropic.claude-sonnet-4-5-20250929-v1:0';

export type LegalFacts = {
  name: string;
  description: string | null;
  hasForms: boolean;
  analytics: string[];
  payments: string[];
};

const SYSTEM_PROMPT = `You draft a first version of a website's legal page as an HTML fragment, using ONLY the facts provided.
Rules:
- Output only h2, h3, p, ul and li elements. No html/head/body/script/style tags, no links except mailto: links.
- Never claim compliance with any specific law (GDPR, CCPA, etc.), certification, or security guarantee. Never invent company names, addresses, registration numbers, jurisdictions, retention periods or contact details: use clearly marked placeholders such as [Company legal name], [Contact email], [Governing law/jurisdiction].
- Only describe data practices the facts support (forms collect what visitors submit; analytics only if listed; payments are processed by the listed provider). Where unknown, say so with a placeholder for the owner to complete.
- Plain language, short sections.`;

const KIND_PROMPT: Record<LegalKind, string> = {
  privacy:
    'Write a Privacy Policy draft: what is collected, why, who it is shared with (listed providers only), cookies/analytics, visitor rights placeholder, contact, changes.',
  terms:
    'Write a Terms of Service draft: acceptance, use of the site, accounts if any (placeholder), payments/refunds (only if payments are listed, otherwise omit), intellectual property, disclaimers, limitation of liability placeholder, governing law placeholder, contact.',
};

export function buildLegalPrompt(kind: LegalKind, facts: LegalFacts) {
  return [
    KIND_PROMPT[kind],
    `Site name: ${facts.name}`,
    `Description: ${facts.description?.trim() || 'not provided'}`,
    `Collects data through forms: ${facts.hasForms ? 'yes' : 'no'}`,
    `Analytics providers: ${facts.analytics.join(', ') || 'none detected'}`,
    `Payment providers: ${facts.payments.join(', ') || 'none detected'}`,
  ].join('\n');
}

const ALLOWED_TAGS = new Set(['h2', 'h3', 'p', 'ul', 'ol', 'li', 'strong', 'em', 'a', 'br']);
const DROPPED_TAGS = new Set(['script', 'style', 'iframe', 'object', 'embed']);

/** Keeps only simple text markup; AI output is never trusted as HTML. */
export function sanitizeDraftHtml(html: string) {
  const clean = (node: { childNodes: unknown[] }): string =>
    (node.childNodes as Array<{
      nodeType: number;
      text: string;
      rawTagName?: string;
      childNodes: unknown[];
      getAttribute(name: string): string | undefined;
    }>)
      .map((child) => {
        if (child.nodeType === 3) return child.text;
        const tag = child.rawTagName?.toLowerCase() ?? '';
        if (DROPPED_TAGS.has(tag)) return '';
        if (!ALLOWED_TAGS.has(tag)) return clean(child);
        if (tag === 'br') return '<br>';
        const inner = clean(child);
        if (tag === 'a') {
          const href = child.getAttribute('href') ?? '';
          return /^mailto:[^\s"'<>]+$/i.test(href) ? `<a href="${href}">${inner}</a>` : inner;
        }
        return `<${tag}>${inner}</${tag}>`;
      })
      .join('');
  return clean(parse(html)).trim();
}

export function renderLegalPage(kind: LegalKind, siteName: string, bodyHtml: string) {
  const title = kind === 'privacy' ? 'Privacy Policy' : 'Terms of Service';
  const escapedName = siteName.replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title} – ${escapedName}</title>
<meta name="description" content="${title} for ${escapedName}.">
<style>body{font-family:system-ui,sans-serif;max-width:46rem;margin:2rem auto;padding:0 1rem;line-height:1.6}.draft-notice{background:#fff3cd;border:1px solid #e0c36a;padding:.75rem 1rem;border-radius:.5rem}</style>
</head>
<body>
<p class="draft-notice" data-legal-draft="true"><strong>${LEGAL_NOTICE}</strong></p>
<h1>${title}</h1>
${bodyHtml}
<p><a href="index.html">Back to home</a></p>
</body>
</html>
`;
}

/** Generates a draft with the model; throws if the model is unavailable or returns nothing usable. */
export async function generateLegalDraft(kind: LegalKind, facts: LegalFacts) {
  const response = await getAnthropicClient().messages.create({
    model: MODEL,
    max_tokens: 3500,
    system: SYSTEM_PROMPT,
    messages: [{ role: 'user', content: buildLegalPrompt(kind, facts) }],
  });
  const block = response.content.find((c) => c.type === 'text');
  const body = block && block.type === 'text' ? sanitizeDraftHtml(block.text) : '';
  if (body.length < 200) throw new Error('The AI returned no usable draft.');
  return renderLegalPage(kind, facts.name, body);
}
